import React, {useCallback, useEffect, useState} from 'react';
import axios from 'axios';
import star from './thinsmooth.png';
import helpbutton from './Vector.png';
import slider from './slider.png';

export default function AuroraForecast({Latitude, Longitude, city}){
    const [auroraData, setAuroraData] = useState(null);
    const fetchAurora = useCallback(async () =>{

        try{
        const response = await axios.get(`https://services.swpc.noaa.gov/json/ovation_aurora_latest.json`);
        console.log(response);
        setAuroraData(response.data);
        }
        catch(error){
            console.error(error);
        }
    }, [city]);


    useEffect(()=>{
        fetchAurora();
    }, [fetchAurora]);


    return(
        <div>
            {auroraData ? (
                <div class="auroraForecast">
                    <header id="title">
                        <img src={star} alt='star'></img>
                        <p>Aurora Forecast</p>
                        <img src={helpbutton} alt='helpButton'></img>
                    </header>
                    <p id="Forecast">
                        {auroraData[Longitude*181][Latitude+90]}
                    </p>
                    <div id="slider">
                        <img src={slider} alt='slider'></img>
                    </div>
                </div>
            ) : 
            (
                <></>
            )
        }
        </div>

    )
}
